APP_CSS = '  * { box-sizing: border-box; }\n  body {\n    margin: 0; padding: 16px; font-family: "Segoe UI", system-ui, sans-serif;\n    background: var(--bg); color: var(--text); font-size: 14px;\n    opacity: var(--opacity);\n  }\n  h1 { font-size: 22px; margin: 0 0 8px; }\n  .sub { opacity: .65; font-size: 12px; }\n  .clicker-row { text-align: center; margin-top: 10px; position: relative; }\n  .clicker-msg {\n    position: absolute; top: -34px; left: 0; right: 0; text-align: center;\n    font-size: 13px; color: var(--accent); opacity: 0; transition: opacity .5s;\n    pointer-events: none; white-space: nowrap;\n  }\n  .clicker-msg.show { opacity: 1; }\n  .clicker {\n    min-width: 120px; height: 42px; padding: 0 18px; border-radius: var(--radius-l);\n    background: var(--surface); border: 1px solid var(--widget); color: var(--text);\n    font-size: 15px; line-height: 1; cursor: pointer; vertical-align: middle;\n    transition: transform .08s, background .15s, border-color .15s;\n  }\n  .clicker:hover { background: var(--widget); }\n  .clicker:active, .clicker.pressed {\n    transform: scale(.9);\n    background: var(--accent); border-color: var(--accent); color: var(--bg);\n  }\n  .head { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 14px; }\n  .brand { flex: 1; min-width: 0; }\n  .icon-btn {\n    width: 36px; height: 36px; padding: 0; font-size: 18px; line-height: 1;\n    display: flex; align-items: center; justify-content: center; flex: none;\n  }\n  .logo {\n    display: inline-block;\n    font-family: "Segoe UI", system-ui, sans-serif; font-size: 22px; font-weight: 700;\n    letter-spacing: 0.02em; line-height: 1.15; color: var(--text); white-space: nowrap;\n    user-select: none;\n    animation: logo-bloom 3.5s ease-in-out infinite;\n  }\n  @keyframes logo-bloom {\n    0%, 100% { text-shadow: 0 0 5px var(--accent), 0 0 12px var(--accent), 0 0 24px var(--accent); opacity: .92; }\n    50% { text-shadow: 0 0 8px var(--accent), 0 0 20px var(--accent), 0 0 44px var(--accent); opacity: 1; }\n  }\n  .tabs { display: flex; gap: 8px; margin-bottom: 14px; }\n  .tab {\n    padding: 8px 22px; border: 1px solid var(--surface); border-radius: var(--radius-m);\n    background: var(--surface); color: var(--text); font-size: 14px; cursor: pointer;\n  }\n  .tab.active { background: var(--accent); color: var(--bg); border-color: var(--accent); }\n  .panel { margin-bottom: 4px; }\n  label { display: block; margin: 10px 0 4px; font-size: 13px; opacity: .9; }\n  input[type=text], select {\n    width: 100%; padding: 8px 10px; border-radius: var(--radius-s); border: 1px solid var(--surface);\n    background: var(--widget); color: var(--text); font-size: 14px; outline: none;\n  }\n  input[type=text]:focus, select:focus { border-color: var(--accent); }\n  input:disabled, select:disabled, button:disabled { opacity: .45; }\n  .row { display: flex; gap: 8px; align-items: center; }\n  .row input[type=text] { flex: 1; }\n  .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 16px; }\n  .check { display: flex; align-items: center; gap: 6px; margin: 10px 0 4px; font-size: 13px; }\n  .check input { width: 15px; height: 15px; accent-color: var(--accent); }\n  button {\n    padding: 8px 18px; border: none; border-radius: var(--radius-s); cursor: pointer;\n    background: var(--surface); color: var(--text); font-size: 14px;\n  }\n  button:hover { background: var(--accent); color: var(--bg); }\n  button:disabled:hover { background: var(--surface); color: var(--text); cursor: default; }\n  .actions { margin-top: 16px; display: flex; gap: 8px; align-items: center; }\n  .overlay {\n    position: fixed; inset: 0; background: rgba(0,0,0,.5); z-index: 50;\n  }\n  .sheet {\n    position: fixed; top: 0; right: 0; bottom: 0; width: 330px; max-width: 92vw;\n    background: var(--surface); border-left: 1px solid var(--widget);\n    padding: 14px 16px; overflow-y: auto; z-index: 51;\n    box-shadow: -8px 0 24px rgba(0,0,0,.45);\n  }\n  .sheet-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 4px; }\n  .sheet-title { font-size: 16px; font-weight: 600; }\n  .sheet-body label { margin-top: 14px; }\n  .note { margin-top: 6px; font-size: 12px; opacity: .7; }\n  input[type=number] {\n    box-sizing: border-box; width: 64px; flex: 0 0 64px;\n    padding: 6px 8px; border-radius: var(--radius-s); border: 1px solid var(--surface);\n    background: var(--widget); color: var(--text); font-size: 13px; outline: none; text-align: center;\n  }\n  input[type=number]:focus { border-color: var(--accent); }\n  input[type=range] {\n    flex: 1 1 0; min-width: 0; accent-color: var(--accent); height: 4px;\n  }\n  .settings-box {\n    margin-top: 12px; padding: 10px 12px; border: 1px solid var(--widget);\n    border-radius: var(--radius-m); background: var(--widget);\n  }\n  .settings-box-title {\n    font-size: 11px; font-weight: 600; opacity: .65;\n    text-transform: uppercase; letter-spacing: .4px; margin-bottom: 8px;\n  }\n  .range-row { display: flex; align-items: center; gap: 8px; margin-top: 8px; }\n  .range-row label { display: inline-block; margin: 0; min-width: 0; font-size: 13px; white-space: nowrap; }\n  .pb-wrap { margin-top: 14px; height: 10px; border-radius: var(--radius-s); background: var(--surface); overflow: hidden; }\n  #pb { height: 100%; width: 0; background: var(--accent); transition: width .2s; }\n  #pb.indeterminate { width: 30%; animation: slide 1.2s infinite; }\n  @keyframes slide { 0% { margin-left: -30%; } 100% { margin-left: 100%; } }\n  #status { margin-top: 6px; font-size: 13px; height: 18px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }\n  #log {\n    width: 100%; min-height: 150px; margin-top: 6px; resize: vertical;\n    background: var(--widget); color: var(--text); border: 1px solid var(--surface);\n    border-radius: var(--radius-s); padding: 8px; font-family: Consolas, monospace; font-size: 12px;\n  }\n  #warn {\n    display: none; margin-top: 10px; padding: 8px 12px; border-radius: var(--radius-s);\n    background: rgba(255, 180, 84, .15); border: 1px solid var(--warn); color: var(--warn); font-size: 13px;\n  }\n\n  /* ---- ffmpeg bloom-оверлей: дождь поверх темы ---- */\n  #ffmpeg-overlay {\n    position: fixed; inset: 0; z-index: 999; overflow: hidden;\n    display: flex; align-items: center; justify-content: center;\n    background:\n      radial-gradient(130% 110% at 50% 0%, rgba(40, 47, 80, .72) 0%, rgba(20, 22, 44, .82) 55%, rgba(6, 8, 16, .92) 100%);\n    font-family: "Segoe UI", system-ui, sans-serif;\n    -webkit-backdrop-filter: blur(5px);\n    backdrop-filter: blur(5px);\n  }\n  /* дождь (по мотивам codepen jh3y/WyNdMG: капли со случайными CSS-переменными) */\n  #ffmpeg-rain { position: absolute; inset: 0; overflow: hidden; pointer-events: none; z-index: 1; }\n  #ffmpeg-rain i {\n    position: absolute; top: -30vh; left: var(--x, 50%);\n    width: 2px; height: var(--len, 14vh); border-radius: 3px;\n    background: linear-gradient(180deg, transparent 0%, rgba(205, 230, 255, .9) 60%, rgba(255, 255, 255, .95) 100%);\n    box-shadow: 0 0 6px rgba(140, 200, 255, .35);\n    opacity: var(--op, .6);\n    animation: rain-fall var(--dur, 1s) linear infinite;\n    animation-delay: var(--delay, 0s);\n  }\n  @keyframes rain-fall {\n    0%   { transform: translateY(-30vh); }\n    100% { transform: translateY(150vh); }\n  }\n\n  #ffmpeg-box { position: relative; z-index: 2; text-align: center; color: #eaf6ff; max-width: 600px; }\n  /* заголовок в собственном «box» с размытием фона, чтобы читался поверх индикатора */\n  #ffmpeg-head {\n    display: inline-block; margin-bottom: 30px; padding: 20px 40px;\n    background: rgba(12, 16, 28, .38);\n    -webkit-backdrop-filter: blur(16px); backdrop-filter: blur(16px);\n    border-radius: 22px;\n    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .09), 0 10px 40px rgba(0, 0, 0, .35);\n  }\n  #ffmpeg-title {\n    margin: 0 0 6px; font-size: 44px; font-weight: 700; letter-spacing: .04em;\n    color: #fff; animation: ff-title-bloom 3.6s ease-in-out infinite;\n  }\n  @keyframes ff-title-bloom {\n    0%, 100% { text-shadow: 0 0 14px rgba(130, 225, 255, .6), 0 0 34px rgba(90, 190, 240, .35); }\n    50% { text-shadow: 0 0 22px rgba(130, 225, 255, .9), 0 0 60px rgba(90, 190, 240, .6); }\n  }\n  #ffmpeg-sub { font-size: 15px; opacity: .94; margin: 0; line-height: 1.5; max-width: 440px; }\n\n  /* кнопка в стиле hyperspace (codepen mephysto/poKNxoY) */\n  #ffmpeg-dl {\n    background: #fff; position: relative; border: 1px solid transparent;\n    cursor: pointer; padding: 14px 52px; border-radius: 100px; overflow: hidden;\n    font-size: 19px; width: 320px; height: 74px; color: #000;\n  }\n  #ffmpeg-dl.active {\n    background: #03101f; border: 1px solid rgba(255,255,255,.9);\n  }\n  #ffmpeg-dl span {\n    position: relative; z-index: 20; font-size: 1.05em; text-transform: uppercase;\n    font-weight: 700; letter-spacing: .06em; color: #000;\n  }\n  #ffmpeg-dl.active span { color: #fff; }\n  #ffmpeg-dl canvas {\n    z-index: 10; position: absolute; top: 0; left: 0; width: 100%; height: 100%;\n  }\n\n  /* прогресс-кольцо: заполняется по мере скачивания */\n  #ffmpeg-progress { position: relative; width: 170px; height: 170px; margin: 0 auto; }\n  #ffmpeg-ring { width: 170px; height: 170px; transform: rotate(-90deg); display: block; }\n  #ffmpeg-ring circle { fill: none; stroke-width: 9; }\n  #ffmpeg-ring .ring-bg { stroke: rgba(255, 255, 255, .15); }\n  #ffmpeg-ring .ring-fg {\n    stroke: #fff; stroke-linecap: round;\n    stroke-dasharray: 326.7; stroke-dashoffset: 326.7;\n    transition: stroke-dashoffset .25s linear;\n    filter: drop-shadow(0 0 6px rgba(140, 220, 255, .85));\n  }\n  #ffmpeg-ring.ffmpeg-extracting { animation: ring-spin 1.1s linear infinite; }\n  #ffmpeg-ring.ffmpeg-extracting .ring-fg { stroke-dasharray: 40 286.7; }\n  @keyframes ring-spin { from { transform: rotate(-90deg); } to { transform: rotate(270deg); } }\n  #ffmpeg-percent {\n    position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;\n    font-size: 34px; font-weight: 700; color: #fff; text-shadow: 0 0 12px rgba(140, 220, 255, .9);\n  }\n  #ffmpeg-status { margin-top: 26px; font-size: 15px; min-height: 20px; color: #dff3ff; }\n  #ffmpeg-retry {\n    margin-top: 12px; display: none;\n    background: transparent; border: 1px solid rgba(255,255,255,.55); color: #fff;\n    padding: 8px 26px; border-radius: 40px; cursor: pointer; font-size: 14px;\n  }\n  #ffmpeg-retry:hover { background: rgba(255,255,255,.12); }\n\n  .ffmpeg-hidden { display: none !important; }\n.theme-actions { display: flex; gap: 8px; margin-top: 10px; }\n.theme-actions button {\n  flex: 1; min-width: 0; padding: 8px 10px;\n  display: inline-flex; align-items: center; justify-content: center; gap: 6px;\n  font-size: 13px; line-height: 1; white-space: nowrap;\n  background: transparent; color: var(--text);\n  border: 1px solid var(--widget); border-radius: var(--radius-s);\n  cursor: pointer; transition: border-color .15s, color .15s, background .15s;\n}\n.theme-actions button:hover { border-color: var(--accent); color: var(--accent); background: rgba(255,255,255,.05); }\n.theme-actions button:active { transform: scale(.97); }\n.theme-actions button.done { border-color: var(--accent); color: var(--accent); }\n.theme-actions .ta-ico { font-size: 14px; line-height: 1; opacity: .75; }\n.theme-actions button:hover .ta-ico { opacity: 1; }\n'

APP_JS = '  var THEMES = __THEMES__;\n  var I18N = __I18N__;\n  var LANGS = Object.keys(I18N).filter(function(k) { return I18N[k] && I18N[k].thisLang; });\n  var TRANS_KEYS = ["none", "libx265", "nvenc", "amf", "qsv"];\n  var QUAL_OPTIONS = [\n    ["lossless", "qual.lossless"], ["2k", "2K (1440p)"],\n    ["1080", "1080p"], ["720", "720p"], ["480", "480p"], ["240", "240p"]\n  ];\n  var SUB_OPTIONS = [["off", "subs.off"], ["ru", "subs.ru"], ["en", "subs.en"], ["all", "subs.all"]];\n  var since = 0;\n  var LOG_LINES = 2000; // сколько строк лога держим в textarea\n  var LOG_CHARS = 120000; // порог (~2000 строк) для обрезки без split на каждом poll\n  var busy = false;\n  var activeTab = "video";\n  var curLang = "en";\n  var clicks = 0;\n  var transAvailability = { ffmpeg: true, avail: [] };\n  var ffmpegOverlay = document.getElementById("ffmpeg-overlay");\n  var ffmpegDlBtn = document.getElementById("ffmpeg-dl");\n  var ffmpegRain = document.getElementById("ffmpeg-rain");\n  var ffmpegRing = document.getElementById("ffmpeg-ring");\n  var ffmpegPercent = document.getElementById("ffmpeg-percent");\n  var ffmpegStatus = document.getElementById("ffmpeg-status");\n  var ffmpegRetry = document.getElementById("ffmpeg-retry");\n  var ffmpegFetching = false;\n  var RING_CIRC = 2 * Math.PI * 52;\n\n  /* ---- кнопка-гиперпространство (mephysto/poKNxoY) ---- */\n  (function hyperspaceButton() {\n    var canvas = ffmpegDlBtn.querySelector("canvas");\n    var ctx = canvas.getContext("2d");\n    var PARTICLES = [];\n    var isGoing = false;\n    var W = 0, H = 0, XO = 0, YO = 0;\n    var MAX_Z = 2, MAX_R = 2, Z_SPD = 2;\n\n    function Particle() {\n      this.x = Math.random() * W;\n      this.y = Math.random() * H;\n      this.z = Math.random() * MAX_Z;\n      this.vel = 0.01 * Z_SPD;\n    }\n    Particle.prototype.update = function() { this.z -= this.vel; };\n    Particle.prototype.render = function() {\n      var z = Math.max(this.z, 0.0001);\n      var px = (this.x - XO) / z * 6 + XO;\n      var py = (this.y - YO) / z * 6 + YO;\n      var r = ((MAX_Z - this.z) / MAX_Z) * MAX_R;\n      if (px < 0 || px > W || py < 0 || py > H) this.z = MAX_Z;\n      this.update();\n      ctx.beginPath();\n      ctx.arc(px, py, Math.max(r, 0.4), 0, Math.PI * 2);\n      ctx.fillStyle = "rgba(255,255,255,0.55)";\n      ctx.strokeStyle = "rgba(255,255,255,0.55)";\n      ctx.fill();\n      ctx.stroke();\n    };\n\n    function size() {\n      canvas.width = W = ffmpegDlBtn.offsetWidth;\n      canvas.height = H = ffmpegDlBtn.offsetHeight;\n      XO = W / 2; YO = H / 2;\n      if (W < 10 || H < 10) { canvas.width = W = 640; canvas.height = H = 148; XO = W / 2; YO = H / 2; }\n    }\n    function loop() {\n      requestAnimationFrame(loop);\n      if (!isGoing) { ctx.clearRect(0, 0, W, H); return; }\n      ctx.fillStyle = "rgba(0,0,0,0.28)";\n      ctx.fillRect(0, 0, W, H);\n      for (var i = 0; i < PARTICLES.length; i++) PARTICLES[i].render();\n    }\n\n  function init() {\n      size();\n      PARTICLES = [];\n      var num = 60;\n      for (var i = 0; i < num; i++) PARTICLES.push(new Particle());\n      loop();\n      window.addEventListener("resize", size);\n    }\n    ffmpegDlBtn.addEventListener("click", function() {\n      if (ffmpegFetching) return;\n      ffmpegFetching = true;\n      isGoing = true;\n      ffmpegDlBtn.classList.add("active");\n      ffmpegDlBtn.querySelector("span").style.display = "block";\n      setFfmpegProgress(0);\n      showFfmpegProgress();\n      doFfmpegDownload();\n    });\n    setTimeout(init, 50);\n  })();\n\n  /* ---- дождь (по мотивам codepen jh3y/WyNdMG) ---- */\n  (function buildRain() {\n    var frag = document.createDocumentFragment();\n    var drops = 90;\n    for (var i = 0; i < drops; i++) {\n      var d = document.createElement("i");\n      d.style.setProperty("--x", (Math.random() * 100).toFixed(2) + "vw");\n      d.style.setProperty("--len", (9 + Math.random() * 16).toFixed(2) + "vh");\n      d.style.setProperty("--dur", (0.6 + Math.random() * 1.4).toFixed(2) + "s");\n      d.style.setProperty("--delay", (Math.random() * 2.5).toFixed(2) + "s");\n      d.style.setProperty("--op", (0.25 + Math.random() * 0.6).toFixed(2));\n      frag.appendChild(d);\n    }\n    ffmpegRain.appendChild(frag);\n  })();\n\n  function setFfmpegProgress(pct) {\n    var v = Math.max(0, Math.min(100, pct || 0));\n    ffmpegRing.classList.remove("ffmpeg-extracting");\n    ffmpegRing.querySelector(".ring-fg").style.strokeDashoffset = (RING_CIRC * (1 - v / 100)).toFixed(1);\n    ffmpegPercent.textContent = String(Math.round(v)) + "%";\n  }\n  function setFfmpegExtracting() {\n    ffmpegRing.classList.add("ffmpeg-extracting");\n    ffmpegPercent.textContent = "\\u2026";\n  }\n  function showFfmpegProgress() {\n    ffmpegDlBtn.classList.add("ffmpeg-hidden");\n    document.getElementById("ffmpeg-progress").classList.remove("ffmpeg-hidden");\n  }\n  function updateFfmpegStatus(text) {\n    ffmpegStatus.classList.remove("ffmpeg-hidden");\n    ffmpegStatus.textContent = text;\n  }\n\n  async function doFfmpegDownload() {\n    try {\n      await pywebview.api.start_ffmpeg_download();\n    } catch (e) {}\n  }\n\n  function t(key) {\n    var d = I18N[curLang] || I18N.ru;\n    if (d && d[key] !== undefined) return d[key];\n    if (I18N.ru[key] !== undefined) return I18N.ru[key];\n    return key;\n  }\n\n  function fillSelect(id, opts, keepValue) {\n    var sel = document.getElementById(id);\n    if (!keepValue) keepValue = sel.value;\n    sel.innerHTML = "";\n    opts.forEach(function(o) {\n      var opt = document.createElement("option");\n      opt.value = o[0];\n      opt.textContent = t(o[1]);\n      sel.appendChild(opt);\n    });\n    sel.value = keepValue;\n  }\n\n  function buildThemeOptions() {\n    var sel = document.getElementById("theme");\n    var keep = sel.value;\n    sel.innerHTML = "";\n    Object.keys(THEMES).forEach(function(k) {\n      var th = THEMES[k] || {};\n      if (th.hidden === true) return;\n      var opt = document.createElement("option");\n      opt.value = k;\n      var label = (I18N[curLang] || I18N.ru || {})["theme_" + k];\n      if (label === undefined && (I18N.ru || {})["theme_" + k] !== undefined) {\n        label = I18N.ru["theme_" + k];\n      }\n      if (label === undefined) label = th.label || k;\n      opt.textContent = label;\n      sel.appendChild(opt);\n    });\n    sel.value = keep;\n    if (sel.value === "") {\n      var _f = sel.querySelector("option");\n      sel.value = _f ? _f.value : "";\n    }\n  }\n  function buildSubsOptions() { fillSelect("subs", SUB_OPTIONS); }\n  function buildQualOptions() { fillSelect("qual", QUAL_OPTIONS); }\n  function buildTranscodeOptions() {\n    var sel = document.getElementById("transcode");\n    var prev = sel.value;\n    sel.innerHTML = "";\n    var missing = [];\n    TRANS_KEYS.forEach(function(key) {\n      var o = document.createElement("option");\n      o.value = key;\n      var label = t("trans." + key);\n      if (key !== "none" && (!transAvailability.ffmpeg || transAvailability.avail.indexOf(key) === -1)) {\n        o.disabled = true;\n        missing.push(label);\n        o.textContent = label + " " + t("trans.unavailable");\n      } else {\n        o.textContent = label;\n      }\n      sel.appendChild(o);\n    });\n    sel.value = prev;\n    var note = document.getElementById("transcode-note");\n    if (!transAvailability.ffmpeg) {\n      note.textContent = t("trans.note.noffmpeg");\n    } else if (missing.length) {\n      note.textContent = t("trans.note.missing") + missing.join(", ") + ".";\n    } else {\n      note.textContent = "";\n    }\n  }\n  function buildLangOptions() {\n    fillSelect("lang", LANGS.filter(function(k) {\n      return I18N[k] && I18N[k]["thisLang"];\n    }).map(function(k) {\n      return [k, I18N[k]["thisLang"]];\n    }));\n  }\n\n  function renderClicker() {\n    var btn = document.getElementById("clicker");\n    btn.textContent = clicks === 0 ? t("clicker.hint") : clicks;\n  }\n  function clickerMessages() {\n    var d = I18N[curLang] || I18N.ru || {};\n    var arr = d["clicker.messages"];\n    if (!Array.isArray(arr) && I18N.ru) arr = I18N.ru["clicker.messages"];\n    return Array.isArray(arr) ? arr : [];\n  }\n  function flashClickerMsg() {\n    var arr = clickerMessages();\n    if (!arr.length) return;\n    var el = document.getElementById("clicker-msg");\n    el.textContent = arr[Math.floor(Math.random() * arr.length)];\n    el.classList.add("show");\n    setTimeout(function() { el.classList.remove("show"); }, 1400);\n  }\n\n  function applyI18n() {\n    document.querySelectorAll("[data-i18n]").forEach(function(el) {\n      el.textContent = t(el.getAttribute("data-i18n"));\n    });\n    document.querySelectorAll("[data-i18n-title]").forEach(function(el) {\n      el.title = t(el.getAttribute("data-i18n-title"));\n    });\n    buildThemeOptions();\n    buildSubsOptions();\n    buildQualOptions();\n    buildTranscodeOptions();\n    buildLangOptions();\n    document.getElementById("lang").value = curLang;\n    document.documentElement.lang = curLang;\n    renderClicker();\n    if (!busy) document.getElementById("status").textContent = t("status.ready");\n  }\n\n  function applyTheme(key) {\n    var c = THEMES[key] || THEMES.scarred_mind || {};\n    function pick(v, d) { return v !== undefined && v !== null ? v : d; }\n    var root = document.documentElement.style;\n    root.setProperty("--bg", pick(c.bg, "#0c1622"));\n    root.setProperty("--surface", pick(c.surface, "#1f2b29"));\n    root.setProperty("--widget", pick(c.widget, "#23444b"));\n    root.setProperty("--text", pick(c.text, "#dcdedd"));\n    root.setProperty("--accent", pick(c.accent, "#628d7c"));\n    root.setProperty("--warn", pick(c.warn, "#ffb454"));\n    root.setProperty("--radius-s", pick(c.radius_s, 6) + "px");\n    root.setProperty("--radius-m", pick(c.radius_m, 8) + "px");\n    root.setProperty("--radius-l", pick(c.radius_l, 12) + "px");\n    root.setProperty("--opacity", pick(c.opacity, 1));\n    var cssEl = document.getElementById("theme-style");\n    if (!cssEl) {\n      cssEl = document.createElement("style");\n      cssEl.id = "theme-style";\n      document.head.appendChild(cssEl);\n    }\n    cssEl.textContent = c.css || "";\n  }\n\n  function setBusy(b) {\n    if (b === busy) return;\n    busy = b;\n    document.getElementById("download").disabled = b;\n    document.getElementById("stop").disabled = !b;\n    ["tab-video", "tab-playlist", "url-video", "url-playlist", "settings-btn", "dest", "browse", "group", "theme", "subs", "qual", "transcode", "lang"]\n      .forEach(function(id) { document.getElementById(id).disabled = b; });\n  }\n\n  function switchTab(name) {\n    activeTab = name;\n    document.getElementById("tab-video").classList.toggle("active", name === "video");\n    document.getElementById("tab-playlist").classList.toggle("active", name === "playlist");\n    document.getElementById("panel-video").hidden = name !== "video";\n    document.getElementById("panel-playlist").hidden = name !== "playlist";\n    if (!busy) document.getElementById(name === "video" ? "url-video" : "url-playlist").focus();\n  }\n\n  async function tick() {\n    if (typeof pywebview === "undefined") { setTimeout(tick, 300); return; }\n    try {\n      var st = await pywebview.api.poll(since);\n      if (typeof st.log_cursor === "number") since = st.log_cursor;\n      if (st.logs && st.logs.length) {\n        var box = document.getElementById("log");\n        box.value += st.logs.join("\\n") + "\\n";\n        if (box.value.length > LOG_CHARS) {\n          var all = box.value.split("\\n");\n          box.value = all.slice(all.length - LOG_LINES).join("\\n");\n        }\n        box.scrollTop = box.scrollHeight;\n      }\n      setBusy(st.busy);\n      var p = st.progress || {};\n      var bar = document.getElementById("pb");\n      if (p.mode === "indeterminate") { bar.classList.add("indeterminate"); bar.style.width = "30%"; }\n      else { bar.classList.remove("indeterminate"); bar.style.width = (p.value || 0) + "%"; }\n      document.getElementById("status").textContent = st.status || "";\n      if (ffmpegFetching && st.ffmpeg) {\n        var fm = st.ffmpeg;\n        if (fm.downloading || fm.extracting) {\n          showFfmpegProgress();\n          if (fm.extracting) {\n            setFfmpegExtracting();\n            updateFfmpegStatus(t("ffmpeg.extracting"));\n          } else {\n            setFfmpegProgress(fm.pct || 0);\n            updateFfmpegStatus(t("ffmpeg.downloading").replace("{pct}", String(Math.round(fm.pct || 0))));\n          }\n        } else if (fm.ok) {\n          showFfmpegProgress();\n          setFfmpegProgress(100);\n          updateFfmpegStatus(t("ffmpeg.ready"));\n          setTimeout(function() {\n            ffmpegOverlay.classList.add("ffmpeg-hidden");\n            pywebview.api.get_initial().then(function(id) {\n              transAvailability = { ffmpeg: !!id.ffmpeg, avail: id.transcoders || [] };\n              buildTranscodeOptions();\n            });\n            document.getElementById("warn").style.display = "none";\n            document.getElementById("status").textContent = t("status.ready");\n            ffmpegFetching = false;\n          }, 500);\n        } else if (fm.error) {\n          showFfmpegProgress();\n          document.getElementById("ffmpeg-progress").classList.add("ffmpeg-hidden");\n          ffmpegDlBtn.classList.remove("ffmpeg-hidden", "active");\n          ffmpegDlBtn.querySelector("canvas").getContext("2d").clearRect(0, 0, 2000, 2000);\n          updateFfmpegStatus(fm.error);\n          ffmpegRetry.style.display = "inline-block";\n          ffmpegFetching = false;\n        }\n      }\n    } catch (e) {}\n    setTimeout(tick, 200);\n  }\n\n  function collect() {\n    return {\n      url: document.getElementById(activeTab === "video" ? "url-video" : "url-playlist").value.trim(),\n      dest: document.getElementById("dest").value.trim(),\n      playlist: activeTab === "playlist",\n      group: document.getElementById("group").checked,\n      subtitles: document.getElementById("subs").value,\n      quality: document.getElementById("qual").value,\n      transcode: document.getElementById("transcode").value,\n      retries: parseInt(document.getElementById("retries").value, 10) || 10,\n      socket_timeout: parseInt(document.getElementById("socket_timeout").value, 10) || 20,\n    };\n  }\n\n  \n  function reloadThemes() {\n    var btn = document.getElementById("reload-themes");\n    pywebview.api.reload_themes().then(function(newThemes) {\n      THEMES = newThemes;\n      buildThemeOptions();\n      applyI18n();\n      if (btn) {\n        var lbl = btn.querySelector("[data-i18n]");\n        if (lbl) {\n          var txt = lbl.textContent;\n          lbl.textContent = "\\u2713";\n          btn.classList.add("done");\n          setTimeout(function() {\n            lbl.textContent = txt;\n            btn.classList.remove("done");\n          }, 900);\n        }\n      }\n    }).catch(function(e) { console.error("reload themes:", e); });\n  }\n  function openThemesFolder() {\n    pywebview.api.open_themes_folder();\n  }\n\n  function init() {\n    if (window.__initDone) return;\n    window.__initDone = true;\n    pywebview.api.get_initial().then(function(initData) {\n    curLang = initData.settings.language || "en";\n    if (LANGS.indexOf(curLang) === -1) curLang = "en";\n    transAvailability = { ffmpeg: !!initData.ffmpeg, avail: initData.transcoders || [] };\n    buildThemeOptions();\n    buildSubsOptions();\n    buildQualOptions();\n    buildTranscodeOptions();\n    applyI18n();\n    document.getElementById("theme").value = initData.settings.theme || "scarred_mind";\n    document.getElementById("subs").value = initData.settings.subtitles || "en";\n    document.getElementById("qual").value = initData.settings.quality || "lossless";\n    document.getElementById("transcode").value = initData.settings.transcode || "none";\n    document.getElementById("retries").value = initData.settings.retries || 10;\n    document.getElementById("retries-range").value = initData.settings.retries || 10;\n    document.getElementById("socket_timeout").value = initData.settings.socket_timeout || 20;\n    document.getElementById("socket_timeout-range").value = initData.settings.socket_timeout || 20;\n    document.getElementById("lang").value = curLang;\n    applyTheme(document.getElementById("theme").value);\n    document.getElementById("dest").value = initData.default_dir;\n    document.getElementById("group").checked = initData.settings.group_playlist !== false;\n    document.getElementById("status").textContent = t("status.ready");\n    if (!initData.ffmpeg) {\n      document.getElementById("warn").style.display = "block";\n      ffmpegOverlay.classList.remove("ffmpeg-hidden");\n      ffmpegStatus.classList.add("ffmpeg-hidden");\n    }\n    document.getElementById("theme").addEventListener("change", function() {\n      var _t = THEMES[this.value];\n      if (_t && _t.entry) {\n        pywebview.api.set_theme(this.value);\n      } else {\n        applyTheme(this.value); pywebview.api.save_setting("theme", this.value);\n      }\n    });\n    document.getElementById("subs").addEventListener("change", function() {\n      pywebview.api.save_setting("subtitles", this.value);\n    });\n    document.getElementById("qual").addEventListener("change", function() {\n      pywebview.api.save_setting("quality", this.value);\n    });\n    document.getElementById("transcode").addEventListener("change", function() {\n      pywebview.api.save_setting("transcode", this.value);\n    });\n    document.getElementById("retries").addEventListener("change", function() {\n      document.getElementById("retries-range").value = this.value;\n      pywebview.api.save_setting("retries", this.value);\n    });\n    document.getElementById("retries-range").addEventListener("input", function() {\n      document.getElementById("retries").value = this.value;\n      pywebview.api.save_setting("retries", this.value);\n    });\n    document.getElementById("socket_timeout").addEventListener("change", function() {\n      document.getElementById("socket_timeout-range").value = this.value;\n      pywebview.api.save_setting("socket_timeout", this.value);\n    });\n    document.getElementById("socket_timeout-range").addEventListener("input", function() {\n      document.getElementById("socket_timeout").value = this.value;\n      pywebview.api.save_setting("socket_timeout", this.value);\n    });\n    document.getElementById("group").addEventListener("change", function() {\n      pywebview.api.save_setting("group_playlist", this.checked);\n    });\n    document.getElementById("lang").addEventListener("change", function() {\n      curLang = this.value;\n      applyI18n();\n      applyTheme(document.getElementById("theme").value);\n      pywebview.api.save_setting("language", this.value);\n    });\n    document.getElementById("download").addEventListener("click", async function() {\n      var cfg = collect();\n      if (!cfg.url) {\n        document.getElementById("status").textContent = activeTab === "video"\n          ? t("status.enter.video") : t("status.enter.playlist");\n        return;\n      }\n      if (!cfg.playlist && /[?&]list=/.test(cfg.url)) {\n        document.getElementById("status").textContent = t("status.playlist.warning");\n      }\n      var res = await pywebview.api.start_download(cfg);\n      if (res && res.error) document.getElementById("status").textContent = res.error;\n    });\n    document.getElementById("stop").addEventListener("click", function() {\n      pywebview.api.stop_download();\n    });\n    document.getElementById("browse").addEventListener("click", async function() {\n      var p = await pywebview.api.browse_folder();\n      if (p) document.getElementById("dest").value = p;\n    });\n    ffmpegRetry.addEventListener("click", function() {\n      ffmpegRetry.style.display = "none";\n      ffmpegStatus.classList.add("ffmpeg-hidden");\n      ffmpegDlBtn.classList.remove("ffmpeg-hidden");\n      ffmpegFetching = true;\n      ffmpegDlBtn.classList.add("active");\n      setFfmpegProgress(0);\n      showFfmpegProgress();\n      doFfmpegDownload();\n    });\n    document.getElementById("clicker").addEventListener("click", function() {\n      var btn = document.getElementById("clicker");\n      clicks++;\n      btn.classList.add("pressed");\n      setTimeout(function() { btn.classList.remove("pressed"); }, 120);\n      if (clicks % 500 === 0) flashClickerMsg();\n      renderClicker();\n    });\n    function openSettings() {\n      document.getElementById("settings-overlay").hidden = false;\n      document.getElementById("settings-sheet").hidden = false;\n    }\n    function closeSettings() {\n      document.getElementById("settings-overlay").hidden = true;\n      document.getElementById("settings-sheet").hidden = true;\n    }\n    function switchSettingsTab(tab) {\n      var isUi = tab === "ui";\n      document.getElementById("panel-ui").hidden = !isUi;\n      document.getElementById("panel-dl").hidden = isUi;\n      document.getElementById("tab-ui").classList.toggle("active", isUi);\n      document.getElementById("tab-dl").classList.toggle("active", !isUi);\n    }\n    document.getElementById("settings-btn").addEventListener("click", openSettings);\n    document.getElementById("settings-close").addEventListener("click", closeSettings);\n    document.getElementById("reload-themes").addEventListener("click", function() { reloadThemes(); });\n    document.getElementById("open-themes").addEventListener("click", function() { openThemesFolder(); });\n    document.getElementById("settings-overlay").addEventListener("click", closeSettings);\n    document.getElementById("tab-ui").addEventListener("click", function() { switchSettingsTab("ui"); });\n    document.getElementById("tab-dl").addEventListener("click", function() { switchSettingsTab("dl"); });\n    document.addEventListener("keydown", function(ev) {\n      if (ev.key === "Escape") closeSettings();\n    });\n    ["url-video", "url-playlist"].forEach(function(id) {\n      document.getElementById(id).addEventListener("keydown", function(ev) {\n        if (ev.key === "Enter") document.getElementById("download").click();\n      });\n    });\n    document.getElementById("tab-video").addEventListener("click", function() { switchTab("video"); });\n    document.getElementById("tab-playlist").addEventListener("click", function() { switchTab("playlist"); });\n    }).catch(function(e) { console.error("init error:", e); });\n  }\n  if (window.pywebview !== undefined) { init(); }\n  else { window.addEventListener("pywebviewready", init); }\n  setTimeout(tick, 400);'

BASE_TEMPLATE = '<!DOCTYPE html>\n<html lang="ru">\n<head>\n<meta charset="utf-8">\n<title>Synfronia</title>\n<style>\n  :root {\n    --bg: #0c1622; --surface: #1f2b29; --widget: #23444b;\n    --text: #dcdedd; --accent: #628d7c; --warn: #ffb454;\n    --radius-s: 6px; --radius-m: 8px; --radius-l: 12px; --opacity: 1;\n  }\n  :root { __THEME_ROOT__ }\n</style>\n<style id="theme-style">__THEME_CSS__</style>\n<style>\n__APP_CSS__\n</style>\n</head>\n<body>\n  \n<!-- SLOT:head -->\n<div class="head">\n    <div class="brand">\n      <h1 class="logo">Synfronia</h1>\n      <div class="sub" data-i18n="ui.sub">Скачивание видео и плейлистов YouTube (yt-dlp)</div>\n    </div>\n    <button type="button" id="settings-btn" class="icon-btn" data-i18n-title="ui.settings" title="Настройки">&#x2699;&#xFE0E;</button>\n  </div>\n<!-- /SLOT:head -->\n\n\n  \n<!-- SLOT:tabs -->\n<div class="tabs">\n    <button type="button" id="tab-video" class="tab active" data-i18n="tab.video">Видео</button>\n    <button type="button" id="tab-playlist" class="tab" data-i18n="tab.playlist">Плейлист</button>\n  </div>\n<!-- /SLOT:tabs -->\n\n\n  \n<!-- SLOT:panel-video -->\n<div id="panel-video" class="panel">\n    <label for="url-video" data-i18n="url.video.label">Ссылка на видео:</label>\n    <input type="text" id="url-video" placeholder="https://www.youtube.com/watch?v=…" autofocus>\n  </div>\n<!-- /SLOT:panel-video -->\n\n\n  \n<!-- SLOT:panel-playlist -->\n<div id="panel-playlist" class="panel" hidden>\n    <label for="url-playlist" data-i18n="url.playlist.label">Ссылка на плейлист:</label>\n    <input type="text" id="url-playlist" placeholder="https://www.youtube.com/playlist?list=…">\n    <div class="check"><input type="checkbox" id="group"><span data-i18n="group.label">Сгруппировать: плейлист в подпапку с его названием</span></div>\n  </div>\n<!-- /SLOT:panel-playlist -->\n\n\n  \n<!-- SLOT:warn -->\n<div id="warn" data-i18n="warn.ffmpeg">ffmpeg не найден — слияние, субтитры, метаданные и перекодировка будут недоступны.</div>\n<!-- /SLOT:warn -->\n\n\n  \n<!-- SLOT:ffmpeg-overlay -->\n<div id="ffmpeg-overlay" class="ffmpeg-hidden">\n    <div id="ffmpeg-rain"></div>\n    <div id="ffmpeg-box">\n      <div id="ffmpeg-head">\n        <div id="ffmpeg-title">Synfronia</div>\n        <div id="ffmpeg-sub" data-i18n="ffmpeg.overlay_hint">Для слияния видео и аудио, субтитров, метаданных и перекодировки нужен ffmpeg.</div>\n      </div>\n      <div style="position:relative;display:inline-block">\n        <button type="button" id="ffmpeg-dl">\n          <span data-i18n="ffmpeg.download">Загрузить FFmpeg</span>\n          <canvas width="640" height="148"></canvas>\n        </button>\n        <div id="ffmpeg-progress" class="ffmpeg-hidden">\n          <svg id="ffmpeg-ring" viewBox="0 0 120 120">\n            <circle class="ring-bg" cx="60" cy="60" r="52"></circle>\n            <circle class="ring-fg" cx="60" cy="60" r="52"></circle>\n          </svg>\n          <div id="ffmpeg-percent">0%</div>\n        </div>\n      </div>\n      <div id="ffmpeg-status"></div>\n      <button type="button" id="ffmpeg-retry" data-i18n="ffmpeg.download">Загрузить FFmpeg</button>\n    </div>\n  </div>\n<!-- /SLOT:ffmpeg-overlay -->\n\n\n  \n<!-- SLOT:actions -->\n<div class="actions">\n    <button id="download" data-i18n="btn.download">Скачать</button>\n    <button id="stop" disabled data-i18n="btn.stop">Отмена</button>\n  </div>\n<!-- /SLOT:actions -->\n\n\n  \n<!-- SLOT:progress -->\n<div class="pb-wrap"><div id="pb"></div></div>\n  <div id="status">Готов.</div>\n  <textarea id="log" readonly></textarea>\n<!-- /SLOT:progress -->\n\n  \n<!-- SLOT:clicker -->\n<div class="clicker-row">\n    <div id="clicker-msg" class="clicker-msg"></div>\n    <button type="button" id="clicker" class="clicker" data-i18n-title="clicker.title" title="…">Кликни меня~</button>\n  </div>\n<!-- /SLOT:clicker -->\n\n\n  \n<!-- SLOT:settings -->\n<div id="settings-overlay" class="overlay" hidden></div>\n  <div id="settings-sheet" class="sheet" hidden>\n    <div class="sheet-head">\n      <span class="sheet-title" data-i18n="ui.settings">Настройки</span>\n      <button type="button" id="settings-close" class="icon-btn" data-i18n-title="ui.close" title="Закрыть">&#x2715;&#xFE0E;</button>\n    </div>\n    <div class="sheet-body">\n      <div class="tabs">\n        <button type="button" class="tab active" id="tab-ui" data-i18n="sheet.tab.ui">Интерфейс</button>\n        <button type="button" class="tab" id="tab-dl" data-i18n="sheet.tab.dl">Загрузчик</button>\n      </div>\n      <div id="panel-ui">\n        <label for="lang" data-i18n="sheet.lang.label">Язык:</label>\n        <select id="lang"></select>\n        <label for="theme" data-i18n="sheet.theme.label">Тема:</label>\n        <select id="theme"></select>\n        <div class="theme-actions">\n          <button type="button" id="reload-themes"><span class="ta-ico">⟳</span><span data-i18n="sheet.theme.reload">Обновить темы</span></button>\n          <button type="button" id="open-themes"><span class="ta-ico">⤢</span><span data-i18n="sheet.theme.open">Папка тем…</span></button>\n        </div>\n        <label for="dest" data-i18n="sheet.dest.label">Папка скачивания:</label>\n        <div class="row">\n          <input type="text" id="dest">\n          <button type="button" id="browse" data-i18n="sheet.browse">Обзор…</button>\n        </div>\n      </div>\n      <div id="panel-dl" hidden>\n        <label for="subs" data-i18n="sheet.subs.label">Субтитры:</label>\n        <select id="subs"></select>\n        <label for="qual" data-i18n="sheet.qual.label">Ограничение качества:</label>\n        <select id="qual"></select>\n        <label for="transcode" data-i18n="sheet.transcode.label">Перекодировка:</label>\n        <select id="transcode"></select>\n        <div id="transcode-note" class="note"></div>\n        <div class="settings-box">\n          <div class="settings-box-title" data-i18n="sheet.network.label">Сеть</div>\n          <div class="range-row">\n            <label for="retries" data-i18n="sheet.retries.label">Повторы:</label>\n            <input type="range" id="retries-range" min="1" max="50" step="1">\n            <input type="number" id="retries" min="1" max="50" step="1">\n          </div>\n          <div class="range-row">\n            <label for="socket_timeout" data-i18n="sheet.timeout.label">Таймаут (сек.):</label>\n            <input type="range" id="socket_timeout-range" min="1" max="120" step="1">\n            <input type="number" id="socket_timeout" min="1" max="120" step="1">\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n<!-- /SLOT:settings -->\n<script>__APPJS__</script>\n</body>\n</html>'
